    subtotal = calculate_subtotal(lines)
    discount_amount = calculate_discount_amount(subtotal, discount)
    total = (subtotal - discount_amount + calculate_shipping(subtotal)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return {"subtotal": subtotal, "shipping": calculate_shipping(subtotal), "total": total}

